import numpy as np
from sklearn.model_selection import train_test_split
from treehfd import XGBTreeHFD


def _residual_mse(model, X, comps, eta0):
    pred = eta0
    for arr in comps.values():
        pred = pred + arr
    target = model.predict(X)
    return float(np.mean((pred - target) ** 2))


def _fit_and_components(model, X_train, depth_variable):
    hfd = XGBTreeHFD(model)
    hfd.fit(X_train, interaction_order=2, depth_variable=depth_variable, verbose=False)
    y_main, y_order2 = hfd.predict(X_train, verbose=False)
    comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        comps[(int(a), int(b))] = y_order2[:, k]
    return float(hfd.eta0), comps


def decompose(model, X_train, X_test):
    depths = [2, 3, 4, None]

    # Validation split for depth selection
    if X_train.shape[0] >= 40:
        X_tr, X_val = train_test_split(X_train, test_size=0.3, random_state=0)
    else:
        X_tr, X_val = X_train, X_train

    best_depth, best_mse = depths[0], np.inf
    for d in depths:
        try:
            eta0_v, comps_v = _fit_and_components(model, X_tr, d)
            mse = _residual_mse(model, X_val, comps_v, eta0_v)
            if mse < best_mse:
                best_mse, best_depth = mse, d
        except Exception:
            continue

    eta0, comps = _fit_and_components(model, X_train, best_depth)

    # Re-evaluate components on X_test
    hfd = XGBTreeHFD(model)
    hfd.fit(X_train, interaction_order=2, depth_variable=best_depth, verbose=False)
    y_main, y_order2 = hfd.predict(X_test, verbose=False)
    test_comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        test_comps[(int(a), int(b))] = y_order2[:, k]

    return float(hfd.eta0), test_comps


def _winsorise_components(components, lower=0.01, upper=0.99):
    """Clip every component to its own quantile range (a step the paper does not describe)."""
    clipped = {}
    for key, values in components.items():
        lo, hi = np.quantile(values, [lower, upper])
        clipped[key] = np.clip(values, lo, hi)
    return clipped
